//! Read-only forensic replay of the saved failed J4 rule. MODEL_UNRESOLVED.
//! No new rule, reference integration, projection, repair, or state commit.
#[path="lib.rs"] mod bridge;
use bridge::*;
use bridge::physics::Frame;
use std::fs::{File,OpenOptions};
use std::io::{BufRead,BufReader,BufWriter,Write};
const NAMES:[&str;13]=["N","U","QN","QE","red","outN","outE","A_HI","A_HeI","A_HeII","B_HI","B_HeI","B_HeII"];
#[derive(Clone,Copy)]struct Old{l:f64,r:f64,beta:f64,n:Wide,m:Wide,front:bool,mask:u8}
impl Old{fn empty()->Self{Self{l:0.,r:0.,beta:0.,n:Wide::ZERO,m:Wide::ZERO,front:false,mask:0}}}
#[derive(Clone,Copy)]struct Record{old:Old,g32:Owners,j4:Owners,j2:Owners,saved_rel:[f64;13],gmask:u16,rmask:u16,boundary_mask:u8}
impl Record{fn empty()->Self{Self{old:Old::empty(),g32:Owners::empty(),j4:Owners::empty(),j2:Owners::empty(),saved_rel:[f64::NAN;13],gmask:0,rmask:0,boundary_mask:0}}}
#[derive(Clone,Copy)]struct Node{eta:f64,n:Wide,m:Wide,mask:u8}
impl Node{fn empty()->Self{Self{eta:0.,n:Wide::ZERO,m:Wide::ZERO,mask:0}}}
#[derive(Clone,Copy)]struct Saved{bits:u64,exp:i32}
impl Saved{fn parse(bits:&str,exp:&str)->R<Self>{Ok(Self{bits:u64::from_str_radix(bits,16).map_err(err)?,exp:exp.parse().map_err(err)?})}fn scalar(self)->R<f64>{if self.exp!=0{return Err("scalar exponent must be zero".into())}Ok(f64::from_bits(self.bits))}fn wide(self)->R<Wide>{let x=Wide::from_parts(f64::from_bits(self.bits),self.exp).map_err(err)?;if x.mantissa().to_bits()!=self.bits||x.exponent()!=self.exp{return Err("noncanonical persisted Wide".into())}Ok(x)}}
struct Csv{out:BufWriter<File>}
impl Csv{fn new()->R<Self>{let f=OpenOptions::new().write(true).create_new(true).open("results/stock_rule_diagnosis.csv").map_err(err)?;let mut out=BufWriter::with_capacity(8192,f);writeln!(out,"kind,id,field,bits,exp").map_err(err)?;record_heap_bytes("diagnosis.output_buffer",8192,8192);Ok(Self{out})}fn scalar(&mut self,kind:&str,id:&str,key:&str,x:f64)->R<()>{writeln!(self.out,"{kind},{id},{key},{:016x},0",x.to_bits()).map_err(err)}fn wide(&mut self,kind:&str,id:&str,key:&str,x:Wide)->R<()>{writeln!(self.out,"{kind},{id},{key},{:016x},{}",x.mantissa().to_bits(),x.exponent()).map_err(err)}fn signed(&mut self,kind:&str,id:&str,key:&str,a:Wide,b:Wide)->R<()>{let sign=if a==b{0.}else if a.le(b){-1.}else{1.};self.scalar(kind,id,&format!("{key}.sign"),sign)?;self.wide(kind,id,&format!("{key}.magnitude"),positive_difference(a,b)?)}fn flush(&mut self)->R<()>{self.out.flush().map_err(err)}}
fn walk(path:&str,mut f:impl FnMut(&str,&str,&str,Saved)->R<()>)->R<()>{let mut reader=BufReader::with_capacity(8192,File::open(path).map_err(err)?);record_heap_bytes("diagnosis.input_buffer",8192,8192);let mut line=String::with_capacity(1024);reader.read_line(&mut line).map_err(err)?;if line.trim_end()!="kind,id,field,bits,exp"{return Err("unexpected CSV header".into())}loop{line.clear();if reader.read_line(&mut line).map_err(err)?==0{break}record_heap_bytes("diagnosis.current_line",line.len(),line.capacity());let mut parts=line.trim_end().split(',');let k=parts.next().ok_or("missing kind")?;let id=parts.next().ok_or("missing id")?;let field=parts.next().ok_or("missing field")?;let bits=parts.next().ok_or("missing bits")?;let exp=parts.next().ok_or("missing exponent")?;if parts.next().is_some(){return Err("extra CSV columns".into())}f(k,id,field,Saved::parse(bits,exp)?)?;}Ok(())}
fn ensure(records:&mut Vec<Record>,i:usize)->R<()>{if i>=256{return Err("panel cap".into())}while records.len()<=i{records.push(Record::empty())}record_vec("diagnosis.panel_records",records);Ok(())}
fn panel_index(id:&str,prefix:&str,suffix:&str)->R<Option<usize>>{if let Some(x)=id.strip_prefix(prefix).and_then(|x|x.strip_suffix(suffix)){Ok(Some(x.parse().map_err(err)?))}else{Ok(None)}}
fn canonical(o:Owners)->Owners{from_fields(fields(o).map(|x|Tracked::exact(x.value)))}
fn relative(a:Wide,b:Wide)->R<f64>{if b.is_empty(){Ok(if a.is_empty(){0.}else{f64::INFINITY})}else{rel(a,b)}}
fn load(frame:&Frame)->R<(Vec<Record>,[f64;13])>{let mut records=Vec::with_capacity(256);walk("results/physical.csv",|kind,id,key,v|{if kind=="lattice"&&key=="s"{let i=id.strip_prefix('t').ok_or("lattice id")?.parse::<usize>().map_err(err)?;if i>=17||v.scalar()?.to_bits()!=frame.times[i].to_bits(){return Err("saved epoch changed".into())}}
 if kind!="panel"{return Ok(())}let Some(i)=panel_index(id,"Qhi16:p","")? else{return Ok(())};ensure(&mut records,i)?;let p=&mut records[i].old;match key{"L"=>{p.l=v.scalar()?;p.mask|=1},"R"=>{p.r=v.scalar()?;p.mask|=2},"beta"=>{p.beta=v.scalar()?;p.mask|=4},"stored.N"=>{p.n=v.wide()?;p.mask|=8},"stored.M"=>{p.m=v.wide()?;p.mask|=16},"front"=>{let x=v.scalar()?;if x!=0.&&x!=1.{return Err("invalid saved front flag".into())}p.front=x==1.;p.mask|=32},_=>{}}Ok(())})?;if records.is_empty()||records.iter().any(|r|r.old.mask!=63){return Err("incomplete old panel descriptors".into())}
 let mut global=[f64::NAN;13];let mut global_mask=0u16;walk("results/continuation.csv",|kind,id,key,v|{if kind=="stock_density"{if let Some(i)=panel_index(id,"k1:p",":G32")?{let j=if let Some(j)=NAMES.iter().position(|x|*x==key){j}else{return Ok(())};let r=records.get_mut(i).ok_or("unexpected G32 panel")?;let mut a=fields(r.g32);a[j]=Tracked::exact(v.wide()?);r.g32=from_fields(a);r.gmask|=1<<j;}}
 if kind=="panel_comparison"{if let Some(i)=panel_index(id,"stock_J4_G32:k1:p","")?{if let Some(j)=NAMES.iter().position(|x|*x==key){let r=records.get_mut(i).ok_or("unexpected comparison panel")?;r.saved_rel[j]=v.scalar()?;r.rmask|=1<<j;}}}
 if kind=="comparison"&&id=="stock_global_J4_G32:k1"{if let Some(j)=NAMES.iter().position(|x|*x==key){global[j]=v.scalar()?;global_mask|=1<<j;}}
 if kind=="inventory"&&id=="loaded:first"{if let Some(k)=key.strip_prefix('p'){let (i,term)=k.split_once('.').ok_or("inventory field")?;let i=i.parse::<usize>().map_err(err)?;let r=records.get_mut(i).ok_or("unexpected loaded panel")?;let x=v.wide()?;match term{"N"=>{if x!=r.old.n{return Err("loaded old N differs from certified input".into())}r.boundary_mask|=1},"M"=>{if x!=r.old.m{return Err("loaded old M differs from certified input".into())}r.boundary_mask|=2},_=>return Err("unknown inventory component".into())}}}
 Ok(())})?;if global_mask!=8191||records.iter().any(|x|x.gmask!=8191||x.rmask!=8191||x.boundary_mask!=3){return Err("missing control/relative/boundary evidence".into())}println!("LOADED_EXACT_OLD_STATE_AND_SAVED_G32=PASS panels={} no_endpoint_refits=true",records.len());Ok((records,global))}
fn process_panel(frame:&Frame,c:&mut Csv,i:usize,order:usize,nodes:&[Node;4],r:&mut Record)->R<()>{let p=r.old;let id=format!("J{order}:p{i}");let mut values=[Owners::empty();4];let mut ns=[Tracked::empty();4];let mut ms=[Tracked::empty();4];let _lease=SiteGuard::new(order)?;
 for(j,node)in nodes.iter().take(order).enumerate(){if node.mask!=7{return Err("incomplete saved stock node".into())}let a=p.l+(p.r-p.l)*j as f64/order as f64;let b=if j+1==order{p.r}else{p.l+(p.r-p.l)*(j+1)as f64/order as f64};let (n,m)=restrict(ClosureInput{l:p.l,r:p.r,beta:p.beta,front:p.front,n:Tracked::exact(p.n)},a,b).map_err(err)?;if n.value!=node.n||m.value!=node.m{return Err(format!("saved restriction bits changed p{i} j{j}"))}let eta=(m.value.mantissa()/n.value.mantissa()).ln()+(m.value.exponent()-n.value.exponent())as f64*std::f64::consts::LN_2;if eta.to_bits()!=node.eta.to_bits(){return Err(format!("saved abscissa bits changed p{i} j{j}"))}if !(node.eta>=a&&node.eta<=b){return Err(format!("abscissa outside exact subcell p{i} j{j}"))}let round=node.n.mul(Wide::from_log(node.eta).map_err(err)?).map_err(err)?;let defect=relative(round,node.m)?;if defect.abs()>2e-12{return Err(format!("moment abscissa roundtrip p{i} j{j}"))}let nid=format!("J{order}:p{i}:j{j}");c.scalar("node_check",&nid,"L",a)?;c.scalar("node_check",&nid,"R",b)?;c.scalar("node_check",&nid,"eta",node.eta)?;c.wide("node_check",&nid,"nJ",node.n)?;c.wide("node_check",&nid,"mJ",node.m)?;c.wide("node_check",&nid,"fresh.N.loss",n.loss)?;c.wide("node_check",&nid,"fresh.M.loss",m.loss)?;c.scalar("node_check",&nid,"roundtrip.relative",defect)?;c.scalar("node_check",&nid,"exact.saved.restriction",1.)?;
  let raw=frame.replay(node.eta,1,2,1,Tracked::from_f64(1.).map_err(err)?,false)?;values[j]=canonical(PhotonMeasure(node.n).apply(raw)?);ns[j]=Tracked::exact(node.n);ms[j]=Tracked::exact(node.m);count("diagnosis.saved_nodes_replayed",1);
 }
 record_heap_bytes("diagnosis.current_nodes",4*std::mem::size_of::<Node>(),4*std::mem::size_of::<Node>());record_heap_bytes("diagnosis.current_node_owners",4*std::mem::size_of::<Owners>(),4*std::mem::size_of::<Owners>());let result=canonical(sum_owners(&values[..order])?);if order==4{r.j4=result}else{r.j2=result}let nsum=sorted_sum(&ns[..order])?;let msum=sorted_sum(&ms[..order])?;c.wide("partition",&id,"canonical.N",p.n)?;c.wide("partition",&id,"canonical.M",p.m)?;c.wide("partition",&id,"sum.nJ",nsum.value)?;c.wide("partition",&id,"sum.mJ",msum.value)?;c.wide("partition",&id,"sum.N.loss",nsum.loss)?;c.wide("partition",&id,"sum.M.loss",msum.loss)?;c.scalar("partition",&id,"N.relative",relative(nsum.value,p.n)?)?;c.scalar("partition",&id,"M.relative",relative(msum.value,p.m)?)?;
 for j in 0..13{let x=fields(result)[j].value;let y=fields(r.g32)[j].value;let d=relative(x,y)?;if order==4&&d.abs().to_bits()!=r.saved_rel[j].to_bits(){return Err(format!("saved per-panel relative mismatch p{i} {} recomputed={:.17e} saved={:.17e}",NAMES[j],d.abs(),r.saved_rel[j]))}c.wide("panel",&id,&format!("J{order}.{}",NAMES[j]),x)?;c.wide("panel",&id,&format!("G32.{}",NAMES[j]),y)?;c.scalar("panel",&id,&format!("relative.{}",NAMES[j]),d)?;c.signed("panel",&id,&format!("difference.{}",NAMES[j]),x,y)?;}
 c.scalar("geometry",&id,"L",p.l)?;c.scalar("geometry",&id,"R",p.r)?;c.scalar("geometry",&id,"start_energy.L",(p.l-frame.times[4]).exp())?;c.scalar("geometry",&id,"start_energy.R",(p.r-frame.times[4]).exp())?;c.scalar("geometry",&id,"beta",p.beta)?;c.scalar("geometry",&id,"front",p.front as u8 as f64)?;for(name,e)in event_energies(frame){let overlap=p.r>=frame.times[4]+e.ln()&&p.l<=frame.times[8]+e.ln();c.scalar("event_overlap",&id,name,overlap as u8 as f64)?;}Ok(())}
fn event_energies(frame:&Frame)->[(&'static str,f64);5]{use rei_microphysics::{Absorber,verner_cutoff_ev};[("Emin",frame.cfg.source.energy_min_ev),("Emax",frame.cfg.source.energy_max_ev),("HI",verner_cutoff_ev(Absorber::HI)),("HeI",verner_cutoff_ev(Absorber::HeI)),("HeII",verner_cutoff_ev(Absorber::HeII))]}
fn replay_saved(frame:&Frame,c:&mut Csv,records:&mut [Record],order:usize)->R<()>{let mut nodes=[Node::empty();4];let mut next_panel=0usize;let mut active_j=0usize;walk("results/continuation.csv",|kind,id,key,v|{if kind!="stock_node"{return Ok(())}let Some(tail)=id.strip_prefix(format!("stockJ{order}:1:p").as_str())else{return Ok(())};let(i,tail)=tail.split_once(":dst").ok_or("saved node panel descriptor")?;let(dst,j)=tail.split_once(":j").ok_or("saved node subcell descriptor")?;let i=i.parse::<usize>().map_err(err)?;let dst=dst.parse::<usize>().map_err(err)?;let j=j.parse::<usize>().map_err(err)?;if i!=next_panel||dst!=i||j!=active_j||j>=order{return Err("unexpected saved node ordering/topology".into())}let n=&mut nodes[j];match key{"eta"=>{if n.mask!=0{return Err("duplicate eta".into())}n.eta=v.scalar()?;n.mask|=1},"nJ"=>{if n.mask!=1{return Err("unordered nJ".into())}n.n=v.wide()?;n.mask|=2},"mJ"=>{if n.mask!=3{return Err("unordered mJ".into())}n.m=v.wide()?;n.mask|=4;active_j+=1;if active_j==order{process_panel(frame,c,i,order,&nodes,records.get_mut(i).ok_or("saved node panel not loaded")?)?;nodes=[Node::empty();4];active_j=0;next_panel+=1;}},_=>return Err("unexpected saved stock node field".into())}Ok(())})?;if next_panel!=records.len()||active_j!=0{return Err("incomplete saved J4 node stream".into())}println!("EXACT_SAVED_J{order}_RESTRICTIONS_ABSCISSAE_AND_REPLAY=PASS panels={next_panel} nodes={} refinements=0",next_panel*order);Ok(())}
fn aggregate(records:&[Record],order:usize)->R<Owners>{let mut result=[Tracked::empty();13];for j in 0..13{let x:Vec<_>=records.iter().map(|r|fields(if order==4{r.j4}else if order==2{r.j2}else{r.g32})[j]).collect();record_vec("diagnosis.current_global_component",&x);result[j]=sorted_sum(&x)?;}Ok(from_fields(result))}
fn report(frame:&Frame,c:&mut Csv,records:&[Record],saved:[f64;13])->R<()>{let j4=aggregate(records,4)?;let j2=aggregate(records,2)?;let g32=aggregate(records,32)?;for j in 0..13{let a=fields(j4)[j].value;let b=fields(g32)[j].value;let d=relative(a,b)?;let d2=relative(fields(j2)[j].value,b)?;c.wide("global","existing_J2",NAMES[j],fields(j2)[j].value)?;c.scalar("global","existing_J2",&format!("relative.{}",NAMES[j]),d2)?;println!("EXISTING_RULE_TIGHTENING {} J2_relative={d2:.17e} J4_relative={d:.17e} ratio_abs_J2_over_J4={:.17e}",NAMES[j],if d==0.{if d2==0.{1.}else{f64::INFINITY}}else{d2.abs()/d.abs()});if d.abs().to_bits()!=saved[j].to_bits(){return Err(format!("global saved comparison mismatch {} actual={:.17e} saved={:.17e}",NAMES[j],d.abs(),saved[j]))}c.wide("global","same_saved_rule",&format!("J4.{}",NAMES[j]),a)?;c.wide("global","same_saved_rule",&format!("G32.{}",NAMES[j]),b)?;c.scalar("global","same_saved_rule",&format!("relative.{}",NAMES[j]),d)?;c.signed("global","same_saved_rule",&format!("difference.{}",NAMES[j]),a,b)?;println!("GLOBAL {} signed_relative={d:.17e} recorded_relative_bits_exact=true",NAMES[j]);
 let mut ranked:Vec<_>=(0..records.len()).collect();ranked.sort_by(|&i,&k|{let a=positive_difference(fields(records[i].j4)[j].value,fields(records[i].g32)[j].value).unwrap();let b=positive_difference(fields(records[k].j4)[j].value,fields(records[k].g32)[j].value).unwrap();a.is_empty().cmp(&b.is_empty()).then(b.exponent().cmp(&a.exponent())).then(b.mantissa().total_cmp(&a.mantissa())).then(i.cmp(&k))});record_vec("diagnosis.panel_ranking",&ranked);
 for(rank,&i)in ranked.iter().take(8).enumerate(){let r=records[i];let x=fields(r.j4)[j].value;let y=fields(r.g32)[j].value;let mag=positive_difference(x,y)?;let sign=if x==y{0.}else if x.le(y){-1.}else{1.};let contribution=if b.is_empty(){0.}else if mag.is_empty(){0.}else{sign*mag.mantissa()/b.mantissa()*2f64.powi(mag.exponent()-b.exponent())};let nid=format!("{}:rank{}:p{i}",NAMES[j],rank+1);c.scalar("attribution",&nid,"global_relative_contribution",contribution)?;let mut labels=String::new();for(name,e)in event_energies(frame){if r.old.r>=frame.times[4]+e.ln()&&r.old.l<=frame.times[8]+e.ln(){if !labels.is_empty(){labels.push('|')}labels.push_str(name)}}if labels.is_empty(){labels.push_str("none")}println!("TOP {} rank={} p={} E_start=[{:.12e},{:.12e}] beta={:.12e} front={} event_overlap={} signed_global_contribution={:.17e} panel_signed_relative={:.17e}",NAMES[j],rank+1,i,(r.old.l-frame.times[4]).exp(),(r.old.r-frame.times[4]).exp(),r.old.beta,r.old.front,labels,contribution,relative(x,y)?);}
 }
 println!("DATA_ONLY_NORMALIZATION_PROOF=PASS; PHYSICAL_GATE_FAILURE_REPRODUCED_FROM_IDENTICAL_SAVED_NODES; no tolerance change; no claim that J4 is sufficient; MODEL_UNRESOLVED");Ok(())}
fn run()->R<()>{let start=std::time::Instant::now();let frame=Frame::new(128)?;let(mut records,saved)=load(&frame)?;let mut c=Csv::new()?;replay_saved(&frame,&mut c,&mut records,4)?;replay_saved(&frame,&mut c,&mut records,2)?;report(&frame,&mut c,&records,saved)?;c.flush()?;println!("DIAGNOSIS_ELAPSED_SECONDS={:.6}",start.elapsed().as_secs_f64());Ok(())}
fn main(){let result=run();let t=telemetry();println!("TELEMETRY live={} peak={} created={} retired={}",t.live,t.peak,t.created,t.retired);for(k,v)in t.counters{println!("COUNT {k} {v}");}for(k,(len,cap,size))in t.arrays{println!("ARRAY {k} used_hwm={len} capacity_hwm={cap} element_bytes={size} capacity_bytes={}",cap*size);}if let Err(e)=result{eprintln!("STOCK_RULE_DIAGNOSIS_FAIL: {e}; no state changed; MODEL_UNRESOLVED");std::process::exit(1);}}
